import { CourseChapter } from "./courseContent";

const IMG_BASE = "/images/word-course";

export function getWordChapters(): CourseChapter[] {
  return [
    {
      title: "Interface de Microsoft Word",
      description: "Identifier l'interface du logiciel Microsoft Word et en comprendre les principales zones de travail pour une utilisation efficace.",
      sections: [
        { title: "Ouvrir Word et découvrir la fenêtre principale", content: `<div style="text-align:center;margin:15px 0"><img src="${IMG_BASE}/word-interface.jpg" alt="Interface principale de Microsoft Word" style="max-width:100%;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.15)"/></div><p>Microsoft Word est un logiciel de traitement de texte qui permet de créer des documents professionnels ou personnels. Pour commencer à l'utiliser, il faut cliquer sur l'icône Word située sur le bureau ou dans le menu démarrer.</p><p>Une fois lancé, le logiciel ouvre une page d'accueil proposant soit de créer un nouveau document vierge, soit d'ouvrir un document existant. L'utilisateur peut également choisir parmi de nombreux modèles prédéfinis : lettres, CV, rapports, brochures, etc.</p><p><strong>Point clé :</strong> Dès qu'un document est ouvert, l'utilisateur découvre la fenêtre principale composée de plusieurs éléments visuels et fonctionnels. Il est essentiel de comprendre cette interface pour pouvoir travailler efficacement.</p><p>La fenêtre principale se décompose en zones distinctes : la barre de titre en haut, le ruban avec ses onglets, la zone de travail centrale (la page blanche), les règles horizontale et verticale, et la barre d'état en bas.</p><div style="background:#e8f4fd;padding:12px 16px;border-left:4px solid #2196F3;border-radius:4px;margin:12px 0"><strong>💡 À retenir :</strong> Prenez le temps de repérer chaque zone de l'interface. Une bonne connaissance de l'environnement Word vous fera gagner un temps considérable dans votre travail quotidien.</div>` },
        { title: "La barre de titre et les contrôles", content: `<p>Située au centre, la barre de titre affiche le nom du document (par défaut « Document1 » tant que le fichier n'est pas enregistré) et le nom du logiciel.</p><p>À droite se trouvent les icônes de contrôle : <strong>Réduire</strong>, <strong>Agrandir/Restaurer</strong> et <strong>Fermer</strong>. Le statut d'enregistrement automatique (si OneDrive actif) est visible à gauche.</p><p><strong>Astuce :</strong> Si vous travaillez avec OneDrive ou SharePoint, l'enregistrement automatique sauvegarde votre travail en temps réel. Le bouton « Enregistrement automatique » est situé à l'extrémité gauche de la barre de titre.</p><div style="background:#fff3cd;padding:12px 16px;border-left:4px solid #ffc107;border-radius:4px;margin:12px 0"><strong>⚠️ Attention :</strong> Si l'enregistrement automatique est activé, chaque modification est immédiatement sauvegardée. Pensez à créer une copie (Enregistrer sous) avant de faire des modifications importantes sur un document existant.</div>` },
        { title: "Le ruban et les onglets principaux", content: `<p>Le ruban regroupe les commandes principales classées par onglets thématiques :</p><ul><li><strong>Accueil :</strong> Police, taille, couleur, alignement, puces, numérotation, styles rapides, presse-papiers.</li><li><strong>Insertion :</strong> Images, tableaux, liens hypertexte, formes, graphiques, en-têtes/pieds de page, numéros de page.</li><li><strong>Disposition :</strong> Marges, orientation, taille du papier, colonnes, sauts de page et de section, filigrane.</li><li><strong>Références :</strong> Table des matières automatique, notes de bas de page, citations, bibliographie, index.</li><li><strong>Publipostage :</strong> Enveloppes, étiquettes, fusion et publipostage avec source de données externe.</li><li><strong>Révision :</strong> Orthographe et grammaire, thésaurus, commentaires, suivi des modifications, comparaison de documents.</li><li><strong>Affichage :</strong> Modes d'affichage (lecture, page, brouillon), volet de navigation, règle, quadrillage, zoom.</li></ul><p><strong>Point important :</strong> Des onglets contextuels apparaissent automatiquement lorsque vous sélectionnez un objet spécifique (image, tableau, forme). Ils proposent des outils dédiés à cet objet.</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Onglet</th><th>Fonction principale</th><th>Raccourci utile</th></tr><tr style="background:#D6E4F0"><td><strong>Accueil</strong></td><td>Mise en forme du texte</td><td>Alt+L</td></tr><tr><td><strong>Insertion</strong></td><td>Ajout d'objets (images, tableaux)</td><td>Alt+S</td></tr><tr style="background:#D6E4F0"><td><strong>Disposition</strong></td><td>Paramètres de page</td><td>Alt+P</td></tr><tr><td><strong>Références</strong></td><td>Table des matières, notes</td><td>Alt+U</td></tr><tr style="background:#D6E4F0"><td><strong>Révision</strong></td><td>Corrections et commentaires</td><td>Alt+R</td></tr></table>` },
        { title: "Barre d'outils Accès rapide", content: `<p>Située par défaut au-dessus du ruban, elle offre un accès immédiat aux fonctions les plus utilisées : <strong>Enregistrer</strong> (Ctrl+S), <strong>Annuler</strong> (Ctrl+Z) et <strong>Répéter</strong> (Ctrl+Y).</p><p>Elle est entièrement personnalisable : cliquez sur la petite flèche déroulante à droite pour ajouter des raccourcis comme Nouveau document, Impression rapide, Aperçu avant impression, Mode lecture ou Zoom.</p><p><strong>Astuce professionnelle :</strong> Ajoutez les commandes que vous utilisez le plus souvent. Cette barre reste visible en permanence, quel que soit l'onglet actif du ruban, ce qui vous fait gagner un temps précieux.</p><div style="background:#d4edda;padding:12px 16px;border-left:4px solid #28a745;border-radius:4px;margin:12px 0"><strong>✅ Bonne pratique :</strong> Ajoutez au minimum ces commandes à votre barre d'accès rapide : Nouveau, Ouvrir, Impression rapide, Aperçu avant impression et Vérification de l'orthographe.</div>` },
        { title: "Les règles et la barre d'état", content: `<p>Les <strong>règles</strong> (horizontale en haut, verticale à gauche) permettent de positionner les retraits, les marges et les tabulations. Pour les afficher ou les masquer : Affichage > cocher/décocher « Règle ».</p><p>La <strong>barre d'état</strong> (en bas) affiche des informations contextuelles : numéro de page (Page X sur Y), nombre de mots, langue de vérification, niveau de zoom et boutons de modes d'affichage (Lecture, Page, Web).</p><p><strong>Personnalisation :</strong> Cliquez droit sur la barre d'état pour choisir les informations à afficher (nombre de caractères, section, colonne, etc.).</p>` },
        { title: "Les modes d'affichage", content: `<p>Word propose plusieurs modes accessibles via l'onglet Affichage ou les icônes de la barre d'état :</p><ul><li><strong>Mode Page :</strong> L'affichage standard « WYSIWYG » (tel qu'à l'impression). C'est le mode par défaut et le plus utilisé.</li><li><strong>Mode Lecture :</strong> Optimisé pour la lecture confortable, sans distractions. Le texte s'adapte à l'écran.</li><li><strong>Mode Web :</strong> Simule l'affichage comme une page Internet, sans marges ni sauts de page.</li><li><strong>Mode Brouillon :</strong> Affiche uniquement le texte brut pour la rédaction rapide, sans mise en page.</li><li><strong>Mode Plan :</strong> Affiche la structure du document par niveaux de titres. Idéal pour réorganiser un long document.</li></ul><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Mode</th><th>Usage recommandé</th></tr><tr style="background:#D6E4F0"><td><strong>Page</strong></td><td>Travail quotidien, mise en forme</td></tr><tr><td><strong>Lecture</strong></td><td>Relecture de documents longs</td></tr><tr style="background:#D6E4F0"><td><strong>Brouillon</strong></td><td>Rédaction rapide sans distraction</td></tr><tr><td><strong>Plan</strong></td><td>Réorganisation de documents structurés</td></tr></table>` },
        { title: "Personnaliser l'environnement de travail", content: `<p>Microsoft Word offre de nombreuses options de personnalisation pour adapter l'interface à vos besoins :</p><p><strong>Thème de l'application :</strong></p><ul><li>Fichier > Options > Général > Thème Office : Couleur (clair), Gris foncé, Noir, ou Blanc.</li><li>Le thème sombre réduit la fatigue oculaire lors de longues sessions de travail.</li></ul><p><strong>Réduire le ruban :</strong></p><ul><li>Double-cliquez sur un onglet pour réduire le ruban et gagner de l'espace de travail.</li><li>Le raccourci <strong>Ctrl+F1</strong> bascule entre ruban affiché et réduit.</li></ul><p><strong>Zoom :</strong></p><ul><li>Utilisez <strong>Ctrl + molette</strong> de la souris pour zoomer/dézoomer rapidement.</li><li>La barre d'état propose un curseur de zoom en bas à droite.</li><li>Affichage > Zoom > Largeur de page pour adapter le document à la largeur de l'écran.</li></ul><div style="background:#e8f4fd;padding:12px 16px;border-left:4px solid #2196F3;border-radius:4px;margin:12px 0"><strong>💡 Conseil :</strong> Configurez votre environnement une fois pour toutes : thème, barre d'accès rapide, zoom par défaut. Cela améliore significativement votre confort et votre productivité.</div>` },
      ]
    },
    {
      title: "Créer et gérer des documents",
      description: "Créer un nouveau document, l'enregistrer sous différents formats, le modifier et le réorganiser efficacement.",
      sections: [
        { title: "Créer un nouveau document", content: `<div style="text-align:center;margin:15px 0"><img src="${IMG_BASE}/word-gestion-fichiers.jpg" alt="Gestion des fichiers dans Word" style="max-width:100%;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.15)"/></div><p>Deux méthodes principales :</p><ul><li><strong>Écran d'accueil :</strong> Cliquer sur « Nouveau » > « Document vierge » ou choisir un modèle.</li><li><strong>Menu Fichier :</strong> Fichier > Nouveau > Document vierge.</li></ul><p>Le raccourci <strong>Ctrl+N</strong> ouvre instantanément un nouveau document vierge.</p><p><strong>Les modèles :</strong> Word propose des centaines de modèles professionnels (CV, lettres, rapports, brochures, factures). Vous pouvez aussi créer vos propres modèles (.dotx) pour standardiser les documents de votre organisme.</p><div style="background:#d4edda;padding:12px 16px;border-left:4px solid #28a745;border-radius:4px;margin:12px 0"><strong>✅ Exercice pratique :</strong> Ouvrez Word et explorez les modèles disponibles. Essayez d'ouvrir un modèle de CV, un modèle de lettre et un modèle de rapport pour voir les différentes mises en page proposées.</div>` },
        { title: "Enregistrer un document", content: `<p><strong>Enregistrer (Ctrl+S) :</strong> Sauvegarde le travail en cours. La première fois, une fenêtre s'ouvre pour nommer le fichier et choisir l'emplacement (ordinateur, OneDrive, SharePoint).</p><p><strong>Enregistrer sous (F12) :</strong> Crée une copie sous un autre nom, dans un autre emplacement ou dans un autre format :</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Format</th><th>Extension</th><th>Usage</th></tr><tr style="background:#D6E4F0"><td><strong>Document Word</strong></td><td>.docx</td><td>Format standard (recommandé)</td></tr><tr><td><strong>PDF</strong></td><td>.pdf</td><td>Envoi final, non modifiable</td></tr><tr style="background:#D6E4F0"><td><strong>Word 97-2003</strong></td><td>.doc</td><td>Compatibilité anciens systèmes</td></tr><tr><td><strong>OpenDocument</strong></td><td>.odt</td><td>Compatible LibreOffice</td></tr><tr style="background:#D6E4F0"><td><strong>Texte enrichi</strong></td><td>.rtf</td><td>Universel tous traitements de texte</td></tr><tr><td><strong>Modèle Word</strong></td><td>.dotx</td><td>Modèle réutilisable</td></tr></table><p><strong>Conseil professionnel :</strong> Enregistrez régulièrement (toutes les 10-15 minutes) et utilisez un système de versioning dans le nom du fichier (ex : Rapport_v1, Rapport_v2).</p>` },
        { title: "Ouvrir et récupérer des documents", content: `<p><strong>Ouvrir :</strong> Fichier > Ouvrir (Ctrl+O). Naviguez dans vos dossiers locaux ou sur le cloud (OneDrive). Les fichiers récents sont accessibles directement depuis l'écran d'accueil pour un accès rapide.</p><p><strong>Récupération :</strong> En cas de fermeture accidentelle, Word conserve des versions de récupération automatique. Fichier > Informations > Gérer le document > Récupérer des documents non enregistrés.</p><p><strong>Propriétés du document :</strong> Fichier > Informations affiche les métadonnées (auteur, date de création, nombre de mots, dernière modification).</p><div style="background:#fff3cd;padding:12px 16px;border-left:4px solid #ffc107;border-radius:4px;margin:12px 0"><strong>⚠️ Important :</strong> Par défaut, Word enregistre une copie de récupération automatique toutes les 10 minutes. Vous pouvez réduire cet intervalle à 1 minute dans Fichier > Options > Enregistrement > « Enregistrer les informations de récupération automatique toutes les X minutes ».</div>` },
        { title: "Naviguer dans un document long", content: `<p>Pour les documents de plusieurs pages, Word offre des outils de navigation puissants :</p><ul><li><strong>Volet de navigation (Ctrl+F) :</strong> Affiche la structure par titres. Cliquez sur un titre pour y accéder directement.</li><li><strong>Ctrl+G (Atteindre) :</strong> Aller directement à un numéro de page, une section, un signet.</li><li><strong>Ctrl+Début / Ctrl+Fin :</strong> Aller au début / à la fin du document.</li><li><strong>Signets :</strong> Insertion > Signet pour marquer un emplacement et y revenir facilement.</li></ul><p><strong>Astuce :</strong> Utilisez la mini-carte de défilement (clic droit sur la barre de défilement) pour naviguer visuellement dans un long document.</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Raccourci</th><th>Action</th></tr><tr style="background:#D6E4F0"><td>Ctrl+F</td><td>Rechercher / Volet de navigation</td></tr><tr><td>Ctrl+H</td><td>Rechercher et remplacer</td></tr><tr style="background:#D6E4F0"><td>Ctrl+G</td><td>Atteindre (page, section, signet)</td></tr><tr><td>Ctrl+Début</td><td>Aller au début du document</td></tr><tr style="background:#D6E4F0"><td>Ctrl+Fin</td><td>Aller à la fin du document</td></tr><tr><td>Page Haut/Bas</td><td>Défiler d'une page</td></tr></table>` },
        { title: "Modifier et réorganiser le contenu", content: `<p><strong>Édition de base :</strong></p><ul><li><strong>Sélection :</strong> Double-clic (mot), triple-clic (paragraphe), Ctrl+A (tout sélectionner).</li><li><strong>Copier-coller :</strong> Ctrl+C / Ctrl+V. Options de collage : conserver la mise en forme source, fusionner, texte seul.</li><li><strong>Couper :</strong> Ctrl+X pour déplacer du contenu.</li><li><strong>Glisser-déposer :</strong> Sélectionnez du texte et faites-le glisser vers un nouvel emplacement.</li></ul><p><strong>Réorganisation avancée :</strong></p><ul><li><strong>Volet de navigation :</strong> Glissez-déposez des titres pour réorganiser des sections entières.</li><li><strong>Mode Plan :</strong> Montez ou descendez les niveaux de titres et déplacez des blocs complets.</li></ul><p><strong>Annuler/Rétablir :</strong> Ctrl+Z / Ctrl+Y. Word conserve un historique de toutes vos modifications, vous pouvez annuler plusieurs actions successivement.</p><div style="background:#e8f4fd;padding:12px 16px;border-left:4px solid #2196F3;border-radius:4px;margin:12px 0"><strong>💡 Le presse-papiers Office :</strong> Word conserve les 24 derniers éléments copiés. Accédez-y via la petite flèche du groupe Presse-papiers (onglet Accueil) pour coller n'importe quel élément précédemment copié.</div>` },
        { title: "Rechercher et remplacer du texte", content: `<p>L'outil Rechercher et remplacer est indispensable pour travailler efficacement :</p><p><strong>Rechercher (Ctrl+F) :</strong></p><ul><li>Saisissez un mot ou une expression dans le volet de navigation.</li><li>Les occurrences sont surlignées en jaune dans le document.</li><li>Naviguez entre les résultats avec les flèches haut/bas.</li></ul><p><strong>Remplacer (Ctrl+H) :</strong></p><ul><li>Saisissez le texte à rechercher et le texte de remplacement.</li><li>« Remplacer tout » effectue le remplacement dans tout le document en une seule action.</li><li>« Remplacer » avance occurrence par occurrence pour un contrôle précis.</li></ul><p><strong>Options avancées :</strong></p><ul><li><strong>Respecter la casse :</strong> Distingue majuscules/minuscules.</li><li><strong>Mot entier :</strong> Évite les remplacements partiels (ex : « en » dans « vent »).</li><li><strong>Caractères génériques :</strong> Utilisez * et ? pour des recherches complexes.</li><li><strong>Remplacer la mise en forme :</strong> Changez la police, la taille ou le style d'un texte spécifique dans tout le document.</li></ul>` },
      ]
    },
    {
      title: "Mise en forme du texte",
      description: "Mettre en forme un texte et structurer les paragraphes à l'aide des outils de mise en forme avancés.",
      sections: [
        { title: "Mise en forme des caractères", content: `<div style="text-align:center;margin:15px 0"><img src="${IMG_BASE}/word-mise-en-forme.jpg" alt="Options de mise en forme dans Word" style="max-width:100%;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.15)"/></div><p>Via le groupe Police de l'onglet Accueil ou le raccourci Ctrl+D (boîte de dialogue Police complète) :</p><ul><li><strong>Police :</strong> Choisir l'apparence (Arial, Times New Roman, Calibri, Garamond…). Privilégiez les polices professionnelles et lisibles.</li><li><strong>Taille :</strong> Standard : 11pt pour le corps, 14-16pt pour les titres. Utilisez les boutons A↑ et A↓ pour ajuster rapidement.</li><li><strong>Effets :</strong> Gras (Ctrl+G), Italique (Ctrl+I), Souligné (Ctrl+U), Barré, Exposant (Ctrl+Shift++), Indice (Ctrl+=).</li><li><strong>Couleur de police :</strong> Modifier la teinte des caractères. Utilisez des couleurs sobres pour un rendu professionnel.</li><li><strong>Surlignage :</strong> Mettre en évidence avec un fond coloré pour attirer l'attention.</li><li><strong>Effets de texte :</strong> Ombre, reflet, luminescence pour les titres décoratifs.</li></ul><p><strong>Conseil :</strong> Limitez le nombre de polices à 2-3 maximum par document pour un aspect professionnel cohérent.</p><div style="background:#f8d7da;padding:12px 16px;border-left:4px solid #dc3545;border-radius:4px;margin:12px 0"><strong>❌ Erreur fréquente :</strong> Utiliser trop de polices, tailles et couleurs différentes dans un même document. Cela donne un aspect brouillon et non professionnel. Limitez-vous à 2 polices et 3 couleurs maximum.</div>` },
        { title: "Structurer les paragraphes", content: `<p><strong>Alignement :</strong></p><ul><li><strong>Gauche (Ctrl+L) :</strong> Standard pour le texte courant.</li><li><strong>Centré (Ctrl+E) :</strong> Pour les titres et en-têtes.</li><li><strong>Droit (Ctrl+R) :</strong> Pour les dates, signatures.</li><li><strong>Justifié (Ctrl+J) :</strong> Le texte s'étend sur toute la largeur. Aspect professionnel mais peut créer des espaces excessifs.</li></ul><p><strong>Retraits :</strong></p><ul><li><strong>Retrait de première ligne :</strong> Décale la première ligne de chaque paragraphe (1,25 cm standard).</li><li><strong>Retrait négatif :</strong> La première ligne dépasse vers la gauche (utile pour les listes numérotées).</li><li><strong>Retrait gauche/droit :</strong> Décale tout le paragraphe.</li></ul><p><strong>Interlignes :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Interligne</th><th>Valeur</th><th>Usage recommandé</th></tr><tr style="background:#D6E4F0"><td>Simple</td><td>1,0</td><td>Documents denses, tableaux</td></tr><tr><td>Standard</td><td>1,15</td><td>Valeur par défaut de Word</td></tr><tr style="background:#D6E4F0"><td>Aéré</td><td>1,5</td><td>Documents professionnels (recommandé)</td></tr><tr><td>Double</td><td>2,0</td><td>Manuscrits, documents à corriger</td></tr></table><p><strong>Espacement avant/après :</strong> Ajoutez de l'espace entre les paragraphes pour aérer le document (6pt à 12pt recommandé).</p>` },
        { title: "Les styles : clé de la productivité", content: `<p>Les styles sont l'outil le plus puissant de Word pour une mise en forme cohérente et professionnelle :</p><p><strong>Styles prédéfinis :</strong></p><ul><li><strong>Titre 1, Titre 2, Titre 3 :</strong> Structurent le document et permettent de générer automatiquement une table des matières.</li><li><strong>Normal :</strong> Le style par défaut pour le texte courant.</li><li><strong>Citation, Sous-titre, Emphase :</strong> Pour des usages spécifiques.</li></ul><p><strong>Créer un style personnalisé :</strong></p><ol><li>Mettez en forme un paragraphe comme souhaité.</li><li>Sélectionnez-le, puis dans la galerie Styles, cliquez sur « Créer un style ».</li><li>Nommez-le et définissez ses propriétés (police, taille, couleur, espacement).</li></ol><p><strong>Avantage majeur :</strong> Si vous modifiez un style, tous les textes utilisant ce style sont mis à jour automatiquement dans tout le document. C'est la clé pour maintenir la cohérence dans les documents longs.</p><div style="background:#d4edda;padding:12px 16px;border-left:4px solid #28a745;border-radius:4px;margin:12px 0"><strong>✅ Bonne pratique :</strong> Toujours utiliser les styles Titre 1, 2, 3 pour structurer un document. Cela permet de générer automatiquement une table des matières et de naviguer facilement via le volet de navigation.</div>` },
        { title: "Pinceau de mise en forme et raccourcis", content: `<p><strong>Pinceau de mise en forme :</strong> Outil essentiel pour copier rapidement le style d'un texte à un autre :</p><ol><li>Sélectionnez le texte source (celui qui a la bonne mise en forme).</li><li>Cliquez sur l'icône « Reproduire la mise en forme » (pinceau) dans l'onglet Accueil.</li><li>Sélectionnez le texte cible pour y appliquer la mise en forme.</li></ol><p><strong>Astuce :</strong> Double-cliquez sur le pinceau pour appliquer le style plusieurs fois de suite. Appuyez sur Échap pour quitter ce mode.</p><p><strong>Raccourcis de mise en forme essentiels :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#4472C4;color:white"><th>Raccourci</th><th>Action</th><th>Catégorie</th></tr><tr style="background:#D6E4F0"><td>Ctrl+G</td><td>Gras</td><td>Caractère</td></tr><tr><td>Ctrl+I</td><td>Italique</td><td>Caractère</td></tr><tr style="background:#D6E4F0"><td>Ctrl+U</td><td>Souligné</td><td>Caractère</td></tr><tr><td>Ctrl+D</td><td>Boîte de dialogue Police</td><td>Caractère</td></tr><tr style="background:#D6E4F0"><td>Ctrl+Shift+C</td><td>Copier la mise en forme</td><td>Format</td></tr><tr><td>Ctrl+Shift+V</td><td>Coller la mise en forme</td><td>Format</td></tr><tr style="background:#D6E4F0"><td>Ctrl+Espace</td><td>Supprimer la mise en forme</td><td>Format</td></tr><tr><td>Ctrl+L / E / R / J</td><td>Aligner gauche / centre / droite / justifié</td><td>Paragraphe</td></tr></table>` },
        { title: "Listes à puces et numérotées", content: `<p>Les listes structurent l'information de manière visuelle et claire :</p><p><strong>Listes à puces :</strong></p><ul><li>Cliquez sur l'icône « Puces » dans l'onglet Accueil.</li><li>Choisissez parmi les symboles proposés ou personnalisez (image, symbole spécial).</li><li>Utilisez Tab pour créer un sous-niveau, Shift+Tab pour remonter d'un niveau.</li></ul><p><strong>Listes numérotées :</strong></p><ul><li>Cliquez sur l'icône « Numérotation » dans l'onglet Accueil.</li><li>Choisissez le format (1. 2. 3. / a. b. c. / I. II. III.).</li><li>La numérotation se poursuit automatiquement. Clic droit > « Recommencer la numérotation » pour repartir à 1.</li></ul><p><strong>Listes multiniveaux :</strong> Pour les documents complexes (rapports, procédures), utilisez les listes à plusieurs niveaux qui combinent chiffres romains, lettres et numéros (I. A. 1. a.).</p><div style="background:#e8f4fd;padding:12px 16px;border-left:4px solid #2196F3;border-radius:4px;margin:12px 0"><strong>💡 Astuce :</strong> Pour transformer rapidement du texte en liste, sélectionnez les lignes et cliquez sur le bouton Puces ou Numérotation. Word ajoute automatiquement les puces ou numéros à chaque paragraphe sélectionné.</div>` },
        { title: "Tabulations et retraits avancés", content: `<p><strong>Tabulations :</strong> Les tabulations permettent d'aligner le texte en colonnes précises sans utiliser de tableaux.</p><ul><li><strong>Tabulation gauche (L) :</strong> Le texte commence au taquet.</li><li><strong>Tabulation centrée :</strong> Le texte est centré sur le taquet.</li><li><strong>Tabulation droite :</strong> Le texte se termine au taquet.</li><li><strong>Tabulation décimale :</strong> Aligne les nombres sur la virgule.</li></ul><p><strong>Positionnement :</strong> Cliquez sur la règle horizontale pour placer un taquet. Double-cliquez sur un taquet existant pour le configurer précisément.</p><p><strong>Points de suite :</strong> Dans la boîte de dialogue Tabulations, choisissez un point de suite (pointillés, tirets) pour créer des lignes de remplissage comme dans une table des matières.</p>` },
        { title: "Bordures et trames de fond", content: `<p>Les bordures et trames mettent en valeur des paragraphes ou des sections importantes :</p><p><strong>Bordures de paragraphe :</strong></p><ul><li>Sélectionnez le texte > Accueil > Bordures > choisissez le type.</li><li>Options : encadrer tout le paragraphe, bordure en haut/bas uniquement, entre les paragraphes.</li><li>Personnalisez l'épaisseur, le style (continu, pointillé, double) et la couleur.</li></ul><p><strong>Trame de fond :</strong></p><ul><li>Accueil > bouton Trame de fond (icône pot de peinture).</li><li>Ajoutez un fond coloré derrière le texte pour le mettre en valeur.</li><li>Utilisez des couleurs pastel pour un rendu professionnel.</li></ul><p><strong>Encadrés professionnels :</strong> Combinez bordure + trame pour créer des encadrés « Important », « Attention » ou « À retenir » dans vos documents de formation.</p><div style="background:#e8f4fd;border:2px solid #2196F3;padding:12px 16px;border-radius:4px;margin:12px 0"><strong>Exemple d'encadré :</strong> Ce type de mise en forme est idéal pour les points clés, les définitions ou les avertissements dans un support de cours.</div>` },
      ]
    },
    {
      title: "Insérer des objets et éléments visuels",
      description: "Enrichir un document avec des images, tableaux, formes, graphiques et autres éléments visuels.",
      sections: [
        { title: "Insérer et gérer des images", content: `<div style="text-align:center;margin:15px 0"><img src="${IMG_BASE}/word-objets-visuels.jpg" alt="Insertion d'objets visuels dans Word" style="max-width:100%;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.15)"/></div><p>Onglet Insertion > Images. Plusieurs sources disponibles :</p><ul><li><strong>Cet appareil :</strong> Images stockées sur votre ordinateur.</li><li><strong>Images en ligne :</strong> Recherche Bing intégrée pour trouver des images libres de droits.</li><li><strong>Images d'archives :</strong> Bibliothèque d'images, icônes et illustrations Microsoft.</li></ul><p><strong>Disposition du texte (habillage) :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Mode d'habillage</th><th>Comportement</th><th>Usage</th></tr><tr style="background:#D6E4F0"><td>Aligné sur le texte</td><td>Image traitée comme un caractère</td><td>Illustrations dans le flux du texte</td></tr><tr><td>Carré</td><td>Texte entoure l'image en carré</td><td>Photos avec texte autour</td></tr><tr style="background:#D6E4F0"><td>Rapproché</td><td>Texte suit les contours</td><td>Formes irrégulières</td></tr><tr><td>Derrière le texte</td><td>Image en arrière-plan</td><td>Filigranes, logos de fond</td></tr><tr style="background:#D6E4F0"><td>Devant le texte</td><td>Image flotte au-dessus</td><td>Logos, tampons, signatures</td></tr></table><p><strong>Redimensionnement :</strong> Utilisez les poignées d'angle (pas les poignées latérales) pour conserver les proportions. Maintenez Shift pour un redimensionnement précis.</p><p><strong>Retouche :</strong> L'onglet Format d'image permet de modifier la luminosité, le contraste, la couleur, d'ajouter des bordures, des ombres ou des effets artistiques.</p>` },
        { title: "Créer et personnaliser des tableaux", content: `<p><strong>Insertion :</strong> Onglet Insertion > Tableau. Plusieurs méthodes :</p><ul><li><strong>Grille :</strong> Survolez pour choisir le nombre de lignes et colonnes (max 10×8).</li><li><strong>Insérer un tableau :</strong> Pour plus de lignes/colonnes ou des dimensions précises.</li><li><strong>Dessiner un tableau :</strong> Cliquez-glissez pour créer des cellules sur mesure.</li><li><strong>Convertir du texte en tableau :</strong> Sélectionnez un texte tabulé et convertissez-le en tableau.</li></ul><p><strong>Onglet Création du tableau :</strong></p><ul><li>Styles de tableau : appliquez un thème visuel prédéfini.</li><li>Options de style : ligne d'en-tête, ligne de totaux, bandes alternées.</li><li>Bordures et trame : personnalisez l'apparence cellule par cellule.</li></ul><p><strong>Onglet Disposition du tableau :</strong></p><ul><li>Fusionner / Fractionner des cellules.</li><li>Ajuster la hauteur et la largeur des lignes/colonnes.</li><li>Aligner le contenu (haut, milieu, bas / gauche, centré, droit).</li><li>Trier les données du tableau.</li><li>Répéter les lignes de titre sur chaque page (essentiel pour les tableaux longs).</li></ul><div style="background:#d4edda;padding:12px 16px;border-left:4px solid #28a745;border-radius:4px;margin:12px 0"><strong>✅ Exercice :</strong> Créez un tableau de 4 colonnes et 6 lignes. Appliquez un style de tableau avec bandes alternées. Fusionnez les cellules de la première ligne pour créer un titre. Ajoutez des bordures personnalisées.</div>` },
        { title: "Formes, SmartArt et graphiques", content: `<p><strong>Formes :</strong> Insertion > Formes. Sélectionnez parmi rectangles, cercles, flèches, légendes, bulles, étoiles, organigrammes…</p><ul><li>Dessinez par cliquer-glisser puis personnalisez : couleur, contour, effets (ombre, 3D, reflet).</li><li>Les formes peuvent contenir du texte : double-cliquez pour saisir.</li><li>Groupez plusieurs formes pour les déplacer ensemble (Ctrl+clic pour sélection multiple).</li></ul><p><strong>SmartArt :</strong> Insertion > SmartArt pour des diagrammes professionnels :</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Type SmartArt</th><th>Utilisation</th><th>Exemple</th></tr><tr style="background:#D6E4F0"><td>Listes</td><td>Énumérations visuelles</td><td>Points clés d'une formation</td></tr><tr><td>Processus</td><td>Étapes séquentielles</td><td>Procédure qualité</td></tr><tr style="background:#D6E4F0"><td>Cycles</td><td>Processus circulaires</td><td>Cycle d'amélioration continue</td></tr><tr><td>Hiérarchies</td><td>Organigrammes</td><td>Structure d'entreprise</td></tr><tr style="background:#D6E4F0"><td>Relations</td><td>Interconnexions</td><td>Diagramme de Venn</td></tr></table><p><strong>Graphiques :</strong> Insertion > Graphique pour créer des histogrammes, courbes, secteurs, barres directement dans Word avec un mini-tableur Excel intégré.</p>` },
        { title: "En-têtes et pieds de page", content: `<p>Insertion > En-tête ou Pied de page. Choisissez un modèle prédéfini ou créez le vôtre.</p><p><strong>Éléments fréquents :</strong></p><ul><li><strong>Logo de l'organisme :</strong> Insérez une image de petite taille, alignée à gauche ou centrée.</li><li><strong>Numéro de page :</strong> Insertion > Numéro de page (haut, bas, marges, position actuelle).</li><li><strong>Date :</strong> Insertion > Date et heure pour une date dynamique.</li><li><strong>Titre du document :</strong> Via les champs rapides (Insertion > QuickParts > Champs).</li></ul><p><strong>Options avancées :</strong></p><ul><li><strong>Première page différente :</strong> Cochez cette option pour avoir un en-tête/pied spécifique sur la page de garde.</li><li><strong>Pages paires et impaires différentes :</strong> Pour les documents reliés (livre, rapport).</li><li><strong>Lier au précédent :</strong> Décochez pour avoir des en-têtes différents par section.</li></ul>` },
        { title: "Liens hypertexte et signets", content: `<p><strong>Liens hypertexte (Ctrl+K) :</strong></p><ul><li><strong>Vers un site web :</strong> Saisissez l'URL (ex : https://www.example.com).</li><li><strong>Vers un fichier :</strong> Naviguez vers le fichier à lier.</li><li><strong>Vers un emplacement dans le document :</strong> Liez vers un titre ou un signet.</li><li><strong>Vers une adresse e-mail :</strong> Crée un lien « mailto: ».</li></ul><p><strong>Signets :</strong></p><ul><li>Insertion > Signet pour marquer un emplacement dans le document.</li><li>Nommez le signet de manière descriptive (ex : « Section_Budget »).</li><li>Utilisez les signets comme cibles de liens hypertexte ou de renvois.</li></ul><p><strong>Renvois :</strong> Insertion > Renvoi pour créer des références croisées vers des titres, figures, tableaux ou signets. Les renvois se mettent à jour automatiquement si la numérotation change.</p>` },
        { title: "Icônes, modèles 3D et captures d'écran", content: `<p>Word intègre des ressources visuelles modernes directement accessibles :</p><p><strong>Icônes (Insertion > Icônes) :</strong></p><ul><li>Bibliothèque de centaines d'icônes vectorielles classées par catégorie.</li><li>Redimensionnables sans perte de qualité.</li><li>Personnalisables en couleur pour s'adapter à votre charte graphique.</li><li>Idéales pour illustrer des processus, des listes ou des organigrammes.</li></ul><p><strong>Modèles 3D (Insertion > Modèles 3D) :</strong></p><ul><li>Objets 3D rotatifs intégrés directement dans le document.</li><li>Permet de montrer un objet sous tous les angles.</li></ul><p><strong>Capture d'écran (Insertion > Capture d'écran) :</strong></p><ul><li><strong>Fenêtres disponibles :</strong> Insère une capture complète d'une fenêtre ouverte.</li><li><strong>Capture d'écran :</strong> Sélectionnez une zone précise de l'écran à capturer.</li><li>Très utile pour les tutoriels, les manuels utilisateur et les procédures.</li></ul>` },
      ]
    },
    {
      title: "Mise en page et impression professionnelle",
      description: "Gérer la mise en page complète d'un document en vue de son impression ou de sa diffusion.",
      sections: [
        { title: "Définir les marges et l'orientation", content: `<div style="text-align:center;margin:15px 0"><img src="${IMG_BASE}/word-mise-en-page.jpg" alt="Paramètres de mise en page Word" style="max-width:100%;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.15)"/></div><p><strong>Marges :</strong> Disposition > Marges. Choix rapides :</p><ul><li><strong>Normal :</strong> 2,5 cm sur chaque côté (standard).</li><li><strong>Étroit :</strong> 1,27 cm (gain de place).</li><li><strong>Large :</strong> 3,18 cm (aéré, pour annotations).</li><li><strong>Personnalisé :</strong> Définissez des mesures spécifiques pour chaque côté et ajoutez une marge de reliure si nécessaire.</li></ul><p><strong>Orientation :</strong></p><ul><li><strong>Portrait (vertical) :</strong> Standard pour la plupart des documents.</li><li><strong>Paysage (horizontal) :</strong> Pour les tableaux larges, les organigrammes, les calendriers.</li></ul><p><strong>Astuce :</strong> Vous pouvez avoir des pages en portrait ET en paysage dans le même document en utilisant les sauts de section.</p><p><strong>Format du papier :</strong> A4 (standard France/Europe), Letter (standard US), A5 (demi-page), ou format personnalisé.</p>` },
        { title: "Sauts de page et sauts de section", content: `<p><strong>Saut de page (Ctrl+Entrée) :</strong> Force le passage à une nouvelle page. Utilisez-le pour :</p><ul><li>Commencer un nouveau chapitre sur une nouvelle page.</li><li>Éviter que Word ne coupe un paragraphe au mauvais endroit.</li></ul><p><strong>Sauts de section :</strong> Plus puissants, ils permettent d'appliquer des paramètres de mise en page différents à chaque section :</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Type de saut</th><th>Effet</th><th>Usage typique</th></tr><tr style="background:#D6E4F0"><td>Page suivante</td><td>Nouvelle section sur nouvelle page</td><td>Nouveau chapitre</td></tr><tr><td>Continu</td><td>Nouvelle section sur même page</td><td>Colonnes dans le texte</td></tr><tr style="background:#D6E4F0"><td>Page paire</td><td>Section commence sur page paire</td><td>Livres reliés</td></tr><tr><td>Page impaire</td><td>Section commence sur page impaire</td><td>Chapitres de livres</td></tr></table><p><strong>Cas d'usage :</strong> Avoir une page de garde sans numérotation, une section en colonnes au milieu du document, ou un changement d'orientation pour une seule page.</p>` },
        { title: "Colonnes et filigrane", content: `<p><strong>Colonnes :</strong> Disposition > Colonnes pour présenter le texte en plusieurs colonnes comme un journal ou une brochure :</p><ul><li>Choisissez 2 ou 3 colonnes, ou personnalisez la largeur et l'espacement.</li><li>Ajoutez une ligne séparatrice entre les colonnes.</li><li>Appliquez à tout le document ou uniquement à une section.</li></ul><p><strong>Filigrane :</strong> Disposition > Filigrane pour ajouter un texte ou une image en arrière-plan de chaque page :</p><ul><li><strong>Textes prédéfinis :</strong> « CONFIDENTIEL », « BROUILLON », « NE PAS COPIER ».</li><li><strong>Texte personnalisé :</strong> Saisissez votre propre texte, choisissez la police, la taille, la couleur et l'orientation.</li><li><strong>Image :</strong> Utilisez le logo de votre organisme en semi-transparent.</li></ul>` },
        { title: "Bordures de page et couleur d'arrière-plan", content: `<p><strong>Bordures de page :</strong> Disposition > Bordures de page pour encadrer l'ensemble de vos pages :</p><ul><li>Choisissez le style (simple, double, pointillé, ondulé).</li><li>Définissez la largeur et la couleur.</li><li>Option « Illustrations » pour des bordures décoratives (étoiles, arbres, cœurs…).</li></ul><p><strong>Couleur de page :</strong> Disposition > Couleur de page pour un arrière-plan coloré. Attention : cela consomme beaucoup d'encre à l'impression.</p><p><strong>Conseil professionnel :</strong> Pour les documents Qualiopi, privilégiez un fond blanc avec des bordures sobres et le logo de l'organisme en en-tête.</p>` },
        { title: "Aperçu et impression", content: `<p><strong>Aperçu avant impression :</strong> Fichier > Imprimer (Ctrl+P) pour accéder à l'aperçu. C'est une étape essentielle avant toute impression :</p><ul><li>Vérifiez les marges et l'alignement du contenu.</li><li>Contrôlez les sauts de page (pas de titre isolé en bas de page).</li><li>Assurez-vous que les images sont correctement positionnées.</li></ul><p><strong>Options d'impression :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Option</th><th>Description</th></tr><tr style="background:#D6E4F0"><td>Imprimante</td><td>Sélectionnez l'imprimante ou « Microsoft Print to PDF »</td></tr><tr><td>Pages</td><td>Toutes, page courante, ou sélection (ex : 1-3, 5, 7-10)</td></tr><tr style="background:#D6E4F0"><td>Copies</td><td>Nombre de copies et assemblage</td></tr><tr><td>Recto-verso</td><td>Si l'imprimante le permet</td></tr><tr style="background:#D6E4F0"><td>Pages par feuille</td><td>1, 2, 4, 6 pages par feuille physique</td></tr></table><p><strong>Export PDF :</strong> Fichier > Exporter > Créer un document PDF/XPS. Choisissez la qualité (standard pour l'impression, taille minimale pour l'envoi par e-mail).</p>` },
      ]
    },
    {
      title: "Documents longs et structurés",
      description: "Maîtriser les outils pour créer et gérer des documents professionnels longs (rapports, manuels, thèses).",
      sections: [
        { title: "Table des matières automatique", content: `<div style="text-align:center;margin:15px 0"><img src="${IMG_BASE}/word-documents-longs.jpg" alt="Documents longs et structurés dans Word" style="max-width:100%;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.15)"/></div><p>La table des matières (TDM) est générée automatiquement à partir des styles de titres :</p><p><strong>Prérequis :</strong> Utilisez les styles Titre 1, Titre 2, Titre 3 pour structurer votre document.</p><p><strong>Insertion :</strong></p><ol><li>Placez le curseur à l'endroit souhaité (généralement après la page de garde).</li><li>Références > Table des matières > choisissez un style automatique.</li></ol><p><strong>Mise à jour :</strong> Clic droit sur la TDM > « Mettre à jour les champs » > « Mettre à jour toute la table ».</p><p><strong>Personnalisation :</strong></p><ul><li>Nombre de niveaux affichés (1 à 9).</li><li>Points de suite (pointillés entre le titre et le numéro de page).</li><li>Format et mise en forme de chaque niveau.</li></ul><p><strong>Conseil :</strong> Mettez à jour la table des matières juste avant l'impression ou l'export PDF.</p>` },
        { title: "Notes de bas de page et notes de fin", content: `<p><strong>Notes de bas de page :</strong> Apparaissent en bas de la page concernée.</p><ul><li>Références > Insérer une note de bas de page (Ctrl+Alt+F).</li><li>Un numéro apparaît dans le texte, le curseur se positionne en bas de page pour saisir la note.</li></ul><p><strong>Notes de fin :</strong> Regroupées à la fin du document ou de la section.</p><ul><li>Références > Insérer une note de fin (Ctrl+Alt+D).</li></ul><p><strong>Personnalisation :</strong> Lanceur du groupe Notes de bas de page pour modifier la numérotation (1, 2, 3 / i, ii, iii / *, †, ‡), la position et la reprise de numérotation par section.</p>` },
        { title: "Citations et bibliographie", content: `<p>Word gère les citations et la bibliographie automatiquement :</p><p><strong>Ajouter une source :</strong></p><ol><li>Références > Insérer une citation > Ajouter une nouvelle source.</li><li>Renseignez le type (livre, article, site web), l'auteur, le titre, l'année, l'éditeur.</li></ol><p><strong>Insérer une citation :</strong> Placez le curseur et choisissez la source dans la liste. La citation apparaît entre parenthèses (ex : (Dupont, 2023)).</p><p><strong>Générer la bibliographie :</strong> Références > Bibliographie > Insérer la bibliographie. Elle se met à jour automatiquement.</p><p><strong>Styles bibliographiques :</strong> APA, MLA, Chicago, ISO 690, Harvard… Changez de style en un clic.</p>` },
        { title: "Index et tables des illustrations", content: `<p><strong>Index :</strong></p><ol><li>Sélectionnez un terme, Références > Marquer l'entrée.</li><li>Répétez pour tous les termes à indexer.</li><li>En fin de document : Références > Insérer l'index.</li></ol><p><strong>Table des illustrations :</strong></p><ol><li>Ajoutez des légendes à vos images/tableaux : clic droit > Insérer une légende.</li><li>Choisissez le type (Figure, Tableau, Équation) et la numérotation automatique.</li><li>Références > Insérer la table des illustrations.</li></ol><p><strong>Table des tableaux :</strong> Même principe que la table des illustrations, en filtrant sur le type « Tableau ».</p>` },
        { title: "Sections et en-têtes différenciés", content: `<p>Les sauts de section permettent d'avoir des paramètres différents dans chaque partie du document :</p><p><strong>Cas d'usage fréquents :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Section</th><th>En-tête</th><th>Numérotation</th></tr><tr style="background:#D6E4F0"><td>Page de garde</td><td>Aucun</td><td>Aucune</td></tr><tr><td>Sommaire</td><td>Titre du document</td><td>Chiffres romains (i, ii, iii)</td></tr><tr style="background:#D6E4F0"><td>Corps du document</td><td>Titre du chapitre</td><td>Chiffres arabes (1, 2, 3)</td></tr><tr><td>Annexes</td><td>« Annexes »</td><td>Numérotation séparée</td></tr></table><p><strong>Procédure :</strong></p><ol><li>Insérez un saut de section (Disposition > Sauts de page > Page suivante).</li><li>Double-cliquez dans l'en-tête/pied de la nouvelle section.</li><li><strong>Décochez « Lier au précédent »</strong> pour dissocier les sections.</li><li>Modifiez l'en-tête/pied indépendamment.</li></ol>` },
        { title: "Créer une page de garde professionnelle", content: `<p>La page de garde est la première impression de votre document. Word offre plusieurs approches :</p><p><strong>Modèles intégrés :</strong></p><ul><li>Insertion > Page de garde > choisissez parmi les modèles proposés.</li><li>Personnalisez le titre, le sous-titre, la date et l'auteur.</li></ul><p><strong>Page de garde personnalisée :</strong></p><ol><li>Créez une page vierge au début du document.</li><li>Insérez le logo de l'organisme (centré ou en haut à gauche).</li><li>Ajoutez le titre en grand (police 28-36pt, style Titre).</li><li>Sous-titre, date, auteur, version du document.</li><li>Mention de confidentialité si nécessaire.</li><li>Ajoutez un saut de section « Page suivante » pour dissocier.</li></ol><p><strong>Éléments recommandés pour un document Qualiopi :</strong></p><ul><li>Logo de l'organisme</li><li>Référence du document (ex : PRO-QUA-001)</li><li>Version et date de mise à jour</li><li>Auteur et approbateur</li><li>Mention « Document interne » ou « Confidentiel »</li></ul>` },
      ]
    },
    {
      title: "Fonctions avancées et collaboration",
      description: "Maîtriser les outils de révision, le publipostage, la protection et les macros pour un usage professionnel avancé.",
      sections: [
        { title: "Suivi des modifications", content: `<div style="text-align:center;margin:15px 0"><img src="${IMG_BASE}/word-collaboration.jpg" alt="Fonctions de collaboration dans Word" style="max-width:100%;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.15)"/></div><p>Le suivi des modifications est essentiel pour le travail collaboratif :</p><p><strong>Activation :</strong> Révision > Suivi des modifications (Ctrl+Shift+E).</p><p>Toutes les modifications sont visibles :</p><ul><li><strong>Texte ajouté :</strong> Souligné en couleur.</li><li><strong>Texte supprimé :</strong> Barré en couleur.</li><li><strong>Mise en forme modifiée :</strong> Indiquée dans les bulles de marge.</li></ul><p><strong>Traiter les modifications :</strong></p><ul><li><strong>Accepter :</strong> Valide la modification et la rend définitive.</li><li><strong>Refuser :</strong> Annule la modification et restaure l'original.</li><li><strong>Accepter/Refuser toutes :</strong> Traitement en bloc de toutes les modifications.</li></ul><p><strong>Modes d'affichage :</strong> Toutes les marques, Balisage simple, Sans balisage, Original.</p>` },
        { title: "Commentaires et révision", content: `<p><strong>Insérer un commentaire :</strong> Sélectionnez du texte > Révision > Nouveau commentaire (Ctrl+Alt+M).</p><p>Les commentaires apparaissent dans des bulles en marge du document.</p><p><strong>Répondre :</strong> Cliquez sur « Répondre » sous un commentaire pour créer un fil de discussion.</p><p><strong>Résoudre :</strong> Marquez un commentaire comme résolu (il devient grisé mais reste visible).</p><p><strong>Supprimer :</strong> Clic droit > Supprimer le commentaire, ou Révision > Supprimer tous les commentaires.</p><p><strong>Comparaison de documents :</strong> Révision > Comparer pour identifier les différences entre deux versions d'un même document. Word génère un document fusionné montrant tous les changements.</p>` },
        { title: "Le publipostage", content: `<p>Le publipostage permet de créer des documents personnalisés en masse (courriers, étiquettes, e-mails) :</p><p><strong>Étapes :</strong></p><ol><li><strong>Document principal :</strong> Créez le modèle de lettre avec le texte commun.</li><li><strong>Source de données :</strong> Connectez un fichier Excel, une base Access ou des contacts Outlook contenant les données variables (nom, adresse, etc.).</li><li><strong>Champs de fusion :</strong> Insérez les champs dynamiques dans le document (<<Nom>>, <<Adresse>>, <<Ville>>).</li><li><strong>Aperçu :</strong> Vérifiez le résultat pour chaque destinataire.</li><li><strong>Fusion :</strong> Générez tous les documents personnalisés (impression, e-mail, ou nouveau document).</li></ol><p><strong>Règles :</strong> Utilisez des règles SI/ALORS pour personnaliser le contenu selon les données (ex : « Cher Monsieur » ou « Chère Madame »).</p><div style="background:#e8f4fd;padding:12px 16px;border-left:4px solid #2196F3;border-radius:4px;margin:12px 0"><strong>💡 Exemple concret :</strong> Un organisme de formation peut utiliser le publipostage pour envoyer des convocations personnalisées à 50 stagiaires en une seule opération, avec le nom, la date et le lieu de formation adaptés à chaque destinataire.</div>` },
        { title: "Protection du document", content: `<p>Word offre plusieurs niveaux de protection :</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse;margin:12px 0"><tr style="background:#4472C4;color:white"><th>Niveau de protection</th><th>Description</th><th>Sécurité</th></tr><tr style="background:#D6E4F0"><td>Marquer comme final</td><td>Lecture seule (désactivable)</td><td>⭐</td></tr><tr><td>Restreindre la modification</td><td>Autorise uniquement certaines actions</td><td>⭐⭐</td></tr><tr style="background:#D6E4F0"><td>Chiffrer avec mot de passe</td><td>Impossible d'ouvrir sans le mot de passe</td><td>⭐⭐⭐</td></tr><tr><td>Signature numérique</td><td>Garantit intégrité et authenticité</td><td>⭐⭐⭐⭐</td></tr></table><p><strong>Restreindre la modification :</strong> Révision > Restreindre la modification. Options :</p><ul><li>Autoriser uniquement les commentaires.</li><li>Autoriser uniquement le remplissage de formulaires.</li><li>Autoriser uniquement le suivi des modifications.</li><li>Aucune modification (lecture seule).</li></ul>` },
        { title: "Formulaires Word", content: `<p>Word permet de créer des formulaires interactifs avec des champs à remplir :</p><p><strong>Activation :</strong> Fichier > Options > Personnaliser le ruban > cochez « Développeur ».</p><p><strong>Contrôles de contenu :</strong></p><ul><li><strong>Texte enrichi / Texte brut :</strong> Zone de saisie libre.</li><li><strong>Liste déroulante :</strong> Choix parmi des options prédéfinies.</li><li><strong>Case à cocher :</strong> Sélection oui/non.</li><li><strong>Sélecteur de date :</strong> Calendrier pour choisir une date.</li><li><strong>Image :</strong> Zone pour insérer une photo ou un logo.</li></ul><p><strong>Protection :</strong> Une fois le formulaire créé, protégez le document en autorisant uniquement le remplissage des formulaires. Les utilisateurs ne pourront modifier que les champs prévus.</p><div style="background:#d4edda;padding:12px 16px;border-left:4px solid #28a745;border-radius:4px;margin:12px 0"><strong>✅ Application Qualiopi :</strong> Les formulaires Word sont parfaits pour les questionnaires de satisfaction, les fiches d'évaluation et les grilles de suivi que les stagiaires doivent remplir numériquement.</div>` },
        { title: "Macros et automatisation", content: `<p>Les macros automatisent les tâches répétitives dans Word :</p><p><strong>Enregistrer une macro :</strong></p><ol><li>Affichage > Macros > Enregistrer une macro.</li><li>Nommez la macro et attribuez un raccourci clavier ou un bouton.</li><li>Effectuez les actions à automatiser (mise en forme, insertion, remplacement…).</li><li>Arrêtez l'enregistrement.</li></ol><p><strong>Exécuter :</strong> Alt+F8 > sélectionnez la macro > Exécuter.</p><p><strong>Éditeur VBA (Alt+F11) :</strong> Permet de créer des macros plus complexes avec du code Visual Basic.</p><p><strong>Exemple pratique :</strong> Macro pour appliquer automatiquement le format de votre organisme (logo, en-tête, pied de page, styles) à tout nouveau document.</p><p><strong>Attention :</strong> Enregistrez en format .docm pour conserver les macros.</p>` },
        { title: "Coédition et travail en temps réel", content: `<p>Word propose des fonctionnalités de collaboration en temps réel lorsque le document est stocké sur OneDrive ou SharePoint :</p><p><strong>Coédition :</strong></p><ul><li>Plusieurs utilisateurs peuvent modifier le même document simultanément.</li><li>Les curseurs de chaque utilisateur sont visibles avec leur nom et une couleur distincte.</li><li>Les modifications sont synchronisées automatiquement.</li></ul><p><strong>Partage :</strong></p><ul><li>Fichier > Partager > entrez les adresses e-mail des destinataires.</li><li>Définissez les droits : « Peut modifier » ou « Peut afficher ».</li><li>Générez un lien de partage avec expiration si nécessaire.</li></ul><p><strong>Historique des versions :</strong></p><ul><li>Fichier > Informations > Historique des versions.</li><li>Consultez les versions précédentes et restaurez-les si nécessaire.</li><li>Comparez les versions pour identifier les changements.</li></ul><div style="background:#fff3cd;padding:12px 16px;border-left:4px solid #ffc107;border-radius:4px;margin:12px 0"><strong>⚠️ Prérequis :</strong> La coédition nécessite un compte Microsoft 365 et un stockage OneDrive ou SharePoint. La version bureau de Word (hors abonnement) ne prend pas en charge cette fonctionnalité.</div>` },
      ]
    },
    {
      title: "Études de cas et exercices pratiques",
      description: "Appliquer les compétences Word à travers des cas professionnels concrets et des exercices pratiques.",
      sections: [
        { title: "Cas 1 : Créer un rapport professionnel structuré", content: `<div style="text-align:center;margin:15px 0"><img src="${IMG_BASE}/word-exercices.jpg" alt="Exercices pratiques Word" style="max-width:100%;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.15)"/></div><p><strong>Contexte :</strong> Vous devez rédiger un rapport de 20 pages pour votre direction sur le bilan annuel de formation de votre organisme.</p><p><strong>Travail demandé :</strong></p><ol><li><strong>Page de garde :</strong> Logo, titre du rapport, date, auteur, mention « Confidentiel ».</li><li><strong>Sommaire automatique :</strong> Utilisation des styles Titre 1, 2, 3 et génération de la table des matières.</li><li><strong>Corps du rapport :</strong> Introduction, 4 parties principales, conclusion.</li><li><strong>Éléments visuels :</strong> Au moins 2 tableaux, 1 graphique et 3 images avec légendes numérotées.</li><li><strong>En-têtes/pieds :</strong> Logo en en-tête, numérotation de page en pied, première page différente.</li><li><strong>Annexes :</strong> Section distincte avec en-tête « Annexes » et numérotation séparée.</li></ol><p><strong>Compétences mobilisées :</strong> Styles, table des matières, sauts de section, en-têtes différenciés, tableaux, images, numérotation.</p><div style="background:#e8f4fd;padding:12px 16px;border-left:4px solid #2196F3;border-radius:4px;margin:12px 0"><strong>💡 Critères de réussite :</strong> Le document doit contenir une TDM fonctionnelle, des en-têtes/pieds différenciés par section, et des légendes numérotées automatiquement sur les illustrations.</div>` },
        { title: "Cas 2 : Publipostage de convocations", content: `<p><strong>Contexte :</strong> Vous devez envoyer une convocation personnalisée à 15 stagiaires pour une formation « Excel Avancé » prévue du 15 au 17 mars.</p><p><strong>Travail demandé :</strong></p><ol><li><strong>Fichier source :</strong> Créez un tableau Excel avec les colonnes : Civilité, Nom, Prénom, Entreprise, Adresse, CP, Ville, Email.</li><li><strong>Document principal :</strong> Rédigez le modèle de convocation avec l'en-tête de l'organisme, les détails de la formation et les champs de fusion.</li><li><strong>Champs de fusion :</strong> Insérez <<Civilité>>, <<Prénom>>, <<Nom>>, <<Entreprise>>, <<Adresse>>.</li><li><strong>Règle conditionnelle :</strong> Si Civilité = « M. » → « Cher », sinon « Chère ».</li><li><strong>Fusion :</strong> Générez les 15 lettres dans un nouveau document Word.</li></ol><div style="background:#d4edda;padding:12px 16px;border-left:4px solid #28a745;border-radius:4px;margin:12px 0"><strong>✅ Résultat attendu :</strong> 15 lettres de convocation personnalisées, chacune avec le nom, l'adresse et la civilité correcte du stagiaire. Le document final doit être prêt à imprimer.</div>` },
        { title: "Cas 3 : Formulaire d'évaluation interactif", content: `<p><strong>Contexte :</strong> Créer un formulaire d'évaluation de satisfaction que les stagiaires pourront remplir numériquement.</p><p><strong>Travail demandé :</strong></p><ol><li><strong>En-tête :</strong> Logo, titre « Questionnaire de satisfaction – Formation [Intitulé] ».</li><li><strong>Informations stagiaire :</strong> Champs texte pour nom, prénom, entreprise. Sélecteur de date pour la date de formation.</li><li><strong>Évaluation :</strong> Listes déroulantes (Très satisfait / Satisfait / Peu satisfait / Insatisfait) pour chaque critère.</li><li><strong>Commentaires :</strong> Zones de texte enrichi pour les remarques libres.</li><li><strong>Cases à cocher :</strong> « Je recommande cette formation : ☐ Oui ☐ Non ».</li><li><strong>Protection :</strong> Protégez le document pour autoriser uniquement le remplissage des champs.</li></ol>` },
        { title: "Cas 4 : Procédure qualité Qualiopi", content: `<p><strong>Contexte :</strong> Rédiger une procédure qualité conforme au RNQ (Référentiel National Qualité) pour votre organisme de formation.</p><p><strong>Travail demandé :</strong></p><ol><li><strong>Page de garde :</strong> Titre, référence du document (PRO-001), version, date, auteur, approbateur.</li><li><strong>Cartouche de gestion documentaire :</strong> Tableau avec historique des versions (date, version, modifications, auteur).</li><li><strong>Structure obligatoire :</strong> Objet, domaine d'application, documents de référence, responsabilités, description du processus, indicateurs de suivi, annexes.</li><li><strong>Logigramme :</strong> Utilisez SmartArt ou des formes pour illustrer le processus.</li><li><strong>En-têtes :</strong> Référence du document et version sur chaque page.</li></ol><p><strong>Critères qualité :</strong> Le document doit être clair, précis, versionné et traçable, conformément aux exigences Qualiopi.</p>` },
        { title: "Cas 5 : Créer un modèle de courrier professionnel", content: `<p><strong>Contexte :</strong> Créer un modèle (.dotx) réutilisable pour les courriers officiels de votre organisme de formation.</p><p><strong>Travail demandé :</strong></p><ol><li><strong>En-tête :</strong> Logo à gauche, coordonnées de l'organisme à droite (nom, adresse, téléphone, e-mail, SIRET, NDA).</li><li><strong>Zone destinataire :</strong> Bloc adresse aligné à droite avec champs de formulaire (nom, adresse, CP, ville).</li><li><strong>Objet :</strong> Ligne « Objet : » suivie d'un champ texte en gras.</li><li><strong>Corps :</strong> Zone de texte enrichi avec la formule de politesse pré-remplie.</li><li><strong>Pied de page :</strong> Mentions légales, numéro de page.</li><li><strong>Signature :</strong> Bloc signature avec ligne pour la signature manuscrite.</li></ol><p><strong>Enregistrement :</strong> Enregistrez en .dotx dans le dossier des modèles personnalisés pour qu'il apparaisse dans Fichier > Nouveau > Personnel.</p>` },
        { title: "Quiz et auto-évaluation Word", content: `<div style="background:#f8f9fa;padding:15px;border-radius:8px;margin-bottom:15px"><p><strong>Q1 :</strong> Quel raccourci crée un saut de page ?</p><p style="color:#28a745">✅ Réponse : Ctrl+Entrée</p></div><div style="background:#f8f9fa;padding:15px;border-radius:8px;margin-bottom:15px"><p><strong>Q2 :</strong> Comment générer automatiquement une table des matières ?</p><p style="color:#28a745">✅ Réponse : Utiliser les styles Titre 1/2/3 puis Références > Table des matières</p></div><div style="background:#f8f9fa;padding:15px;border-radius:8px;margin-bottom:15px"><p><strong>Q3 :</strong> Comment dissocier les en-têtes entre deux sections ?</p><p style="color:#28a745">✅ Réponse : Insérer un saut de section, puis décocher « Lier au précédent »</p></div><div style="background:#f8f9fa;padding:15px;border-radius:8px;margin-bottom:15px"><p><strong>Q4 :</strong> Quel outil permet de créer des courriers personnalisés en masse ?</p><p style="color:#28a745">✅ Réponse : Le publipostage (onglet Publipostage)</p></div><div style="background:#f8f9fa;padding:15px;border-radius:8px;margin-bottom:15px"><p><strong>Q5 :</strong> Comment protéger un formulaire pour que les utilisateurs ne remplissent que les champs prévus ?</p><p style="color:#28a745">✅ Réponse : Révision > Restreindre la modification > Autoriser uniquement le remplissage de formulaires</p></div><div style="background:#f8f9fa;padding:15px;border-radius:8px;margin-bottom:15px"><p><strong>Q6 :</strong> Quel raccourci ouvre la boîte de dialogue Rechercher et remplacer ?</p><p style="color:#28a745">✅ Réponse : Ctrl+H</p></div><div style="background:#f8f9fa;padding:15px;border-radius:8px;margin-bottom:15px"><p><strong>Q7 :</strong> Comment insérer une image et la positionner librement dans le texte ?</p><p style="color:#28a745">✅ Réponse : Insertion > Images, puis modifier l'habillage du texte (Carré, Devant le texte, etc.)</p></div><div style="background:#f8f9fa;padding:15px;border-radius:8px;margin-bottom:15px"><p><strong>Q8 :</strong> Quelle est la différence entre un saut de page et un saut de section ?</p><p style="color:#28a745">✅ Réponse : Le saut de page force une nouvelle page, le saut de section permet en plus d'appliquer des paramètres de mise en page différents (marges, orientation, en-têtes)</p></div><p style="margin-top:20px"><strong>Grille d'auto-évaluation :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#4472C4;color:white"><th>Compétence</th><th>Non acquis</th><th>En cours</th><th>Acquis</th><th>Maîtrisé</th></tr><tr style="background:#D6E4F0"><td>Créer et enregistrer un document</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr><tr><td>Mettre en forme texte et paragraphes</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr><tr style="background:#D6E4F0"><td>Utiliser les styles et la table des matières</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr><tr><td>Insérer des tableaux et images</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr><tr style="background:#D6E4F0"><td>Gérer les en-têtes et sections</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr><tr><td>Utiliser le suivi des modifications</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr><tr style="background:#D6E4F0"><td>Créer un publipostage</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr><tr><td>Protéger un document</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr><tr style="background:#D6E4F0"><td>Rechercher et remplacer</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr><tr><td>Créer des formulaires interactifs</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td><td style="text-align:center">☐</td></tr></table>` },
      ]
    },
  ];
}
